package com.overcookedrecomp.app.runtime
import java.io.File
import java.security.MessageDigest
enum class ValidationCode{READY,ROOT_MISSING,EXE_MISSING,EXE_OUTSIDE_ROOT,DATA_MISSING,UNITY_CORE_MISSING,UNSUPPORTED_ARCH,IO_ERROR}
data class ValidationReport(val installationId:String,val code:ValidationCode,val message:String,val fingerprint:String="",val checkedFiles:List<String> = emptyList()){val ready:Boolean get()=code==ValidationCode.READY}
/** Conservative validator; never executes an executable. */
class GameValidationPipeline{
 fun validate(g:GameInstallation):ValidationReport{val root=File(g.installRoot);if(!root.isDirectory)return report(g,ValidationCode.ROOT_MISSING,"Folder instalasi tidak ditemukan.");val exe=File(g.executablePath);val data=File(g.dataDirectory);val rootPath=runCatching{root.canonicalFile.toPath()}.getOrElse{return report(g,ValidationCode.IO_ERROR,"Path instalasi tidak dapat dibaca.")};val exePath=runCatching{exe.canonicalFile.toPath()}.getOrElse{return report(g,ValidationCode.IO_ERROR,"Path executable tidak valid.")};if(!exePath.startsWith(rootPath))return report(g,ValidationCode.EXE_OUTSIDE_ROOT,"Executable berada di luar folder instalasi.");if(!exe.isFile||exe.length()==0L)return report(g,ValidationCode.EXE_MISSING,"Executable tidak ditemukan atau kosong.");if(g.architecture !in setOf("x86_64","amd64"))return report(g,ValidationCode.UNSUPPORTED_ARCH,"Arsitektur belum didukung: "+g.architecture);if(!data.isDirectory)return report(g,ValidationCode.DATA_MISSING,"Folder data game tidak ditemukan.");val core=listOf("globalgamemanagers","data.unity3d","level0").map{File(data,it)}.filter{it.isFile&&it.length()>0};if(core.isEmpty())return report(g,ValidationCode.UNITY_CORE_MISSING,"File inti Unity tidak ditemukan.");val managed=File(data,"Managed/Assembly-CSharp.dll");val il2cpp=File(data,"il2cpp_data/Metadata/global-metadata.dat");if(!managed.isFile&&!il2cpp.isFile)return report(g,ValidationCode.UNITY_CORE_MISSING,"Assembly-CSharp.dll atau global-metadata.dat tidak ditemukan.");val hashTarget=if(managed.isFile)managed else il2cpp;val hash=runCatching{sha(hashTarget)}.getOrElse{return report(g,ValidationCode.IO_ERROR,"Fingerprint file gagal dihitung.")};return ValidationReport(g.id,ValidationCode.READY,"Struktur terdeteksi; bukan bukti game dapat dijalankan.",hash,core.map{it.name}+hashTarget.name)}
 private fun report(g:GameInstallation,c:ValidationCode,m:String)=ValidationReport(g.id,c,m)
 private fun sha(f:File):String{val d=MessageDigest.getInstance("SHA-256");f.inputStream().buffered().use{s->val b=ByteArray(65536);while(true){val n=s.read(b);if(n<0)break;d.update(b,0,n)}};return d.digest().joinToString(""){"%02x".format(it)}}
}
